svg.script:
(function () {
  const DURATION = 12000;
  const ease = t => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  const easeOut = t => 1 - Math.pow(1 - t, 3);
  const clamp01 = v => Math.max(0, Math.min(1, v));
  const lerp = (a, b, t) => a + (b - a) * t;

  // Keyframes: [tStart, tEnd, barFrom, barTo, apyFrom, apyTo, pillLabel, activeMilestone]
  const SEGMENTS = [
    [0,     1900, 0,  8,  0.00, 2.45, 'stBTC · APY',    0],
    [1900,  3100, 8,  8,  2.45, 2.45, 'stBTC · APY',    1],
    [3100,  5000, 8,  16, 2.45, 5.98, 'stSTXbtc · APY', 1],
    [5000,  6200, 16, 16, 5.98, 5.98, 'stSTXbtc · APY', 2],
    [6200,  7700, 16, 24, 5.98, 5.99, 'stSTX · APY',    2],
    [7700,  8900, 24, 24, 5.99, 5.99, 'stSTX · APY',    3],
    [8900, 10200, 24, 32, 5.99, 6.64, 'Native · APY',   3],
    [10200,11150, 32, 32, 6.64, 6.64, 'Native · APY',   4],
    [11150,12000, 32, 0,  6.64, 0.00, 'stBTC · APY',    0]
  ];

  const txLogo = document.getElementById('tx-logo');
  const txHead = document.getElementById('tx-head');
  const txSub = document.getElementById('tx-sub');
  const txReadout = document.getElementById('tx-readout');
  const txMilestones = document.getElementById('yield-milestones');

  function fadeWindow(t, inStart, inDur, outStart, outDur) {
    if (t < inStart) return 0;
    if (t < inStart + inDur) return easeOut((t - inStart) / inDur);
    if (t <= outStart) return 1;
    if (t < outStart + outDur) return 1 - ease(clamp01((t - outStart) / outDur));
    return 0;
  }

  const bars = Array.from({ length: 33 }, (_, i) => document.getElementById('b' + i));
  const apyInt = document.getElementById('apy-int');
  const apyD1 = document.getElementById('apy-d1');
  const apyD2 = document.getElementById('apy-d2');
  const apyPill = document.getElementById('apy-pill');

  const milestones = [
    { idx: 8,  tick: document.getElementById('m1-tick'), val: document.getElementById('m1-val'), pct: document.getElementById('m1-pct'), lbl: document.getElementById('m1-lbl') },
    { idx: 16, tick: document.getElementById('m2-tick'), val: document.getElementById('m2-val'), pct: document.getElementById('m2-pct'), lbl: document.getElementById('m2-lbl') },
    { idx: 24, tick: document.getElementById('m3-tick'), val: document.getElementById('m3-val'), pct: document.getElementById('m3-pct'), lbl: document.getElementById('m3-lbl') },
    { idx: 32, tick: document.getElementById('m4-tick'), val: document.getElementById('m4-val'), pct: document.getElementById('m4-pct'), lbl: document.getElementById('m4-lbl') }
  ];

  function updateAt(rawMs) {
    const t = ((rawMs % DURATION) + DURATION) % DURATION;

    // Header visible on frame 0; all texts fade in within <= 460ms
    if (txHead) txHead.setAttribute('opacity', fadeWindow(t, 0, 260, 11500, 480).toFixed(3));
    if (txSub)  txSub.setAttribute('opacity', fadeWindow(t, 90, 280, 11460, 480).toFixed(3));
    if (txReadout) txReadout.setAttribute('opacity', fadeWindow(t, 130, 280, 11440, 480).toFixed(3));
    if (txMilestones) txMilestones.setAttribute('opacity', fadeWindow(t, 160, 280, 11420, 480).toFixed(3));
    let seg = SEGMENTS[0];
    for (let i = 0; i < SEGMENTS.length; i++) {
      if (t >= SEGMENTS[i][0] && t <= SEGMENTS[i][1]) { seg = SEGMENTS[i]; break; }
    }
    const span = Math.max(1, seg[1] - seg[0]);
    const p = ease(Math.max(0, Math.min(1, (t - seg[0]) / span)));
    const barPos = lerp(seg[2], seg[3], p);
    const leadIdx = Math.round(barPos);
    const apy = lerp(seg[4], seg[5], p);

    for (let i = 0; i < bars.length; i++) {
      const el = bars[i];
      if (!el) continue;
      el.setAttribute('class', i < leadIdx ? 'bar-active' : i === leadIdx ? 'bar-lead' : 'bar-inactive');
    }

    const formatted = apy.toFixed(2);
    const parts = formatted.split('.');
    if (apyInt) apyInt.textContent = parts[0];
    if (apyD1) apyD1.textContent = parts[1][0];
    if (apyD2) apyD2.textContent = parts[1][1];
    if (apyPill) apyPill.textContent = seg[6];

    for (let k = 0; k < milestones.length; k++) {
      const m = milestones[k];
      const isCurrent = Math.abs(leadIdx - m.idx) <= 2 && leadIdx >= m.idx - 1 && (seg[7] === k + 1 || (leadIdx >= m.idx && (k === milestones.length - 1 || leadIdx < milestones[k + 1].idx)));
      const isReached = leadIdx >= m.idx;
      if (!m.tick || !m.val || !m.lbl) continue;

      if (isCurrent) {
        m.tick.setAttribute('y2', '20');
        m.tick.setAttribute('stroke', '#6FF26F');
        m.tick.setAttribute('stroke-opacity', '1');
        m.tick.setAttribute('stroke-width', '2.5');
        m.tick.setAttribute('class', 'milestone-glow');
        m.val.setAttribute('fill', '#6FF26F');
        m.val.setAttribute('font-size', '30');
        if (m.pct) m.pct.setAttribute('fill', '#6FF26F');
        m.lbl.setAttribute('fill', '#ffffff');
        m.lbl.setAttribute('font-weight', '600');
      } else if (isReached) {
        m.tick.setAttribute('y2', '16');
        m.tick.setAttribute('stroke', '#6FF26F');
        m.tick.setAttribute('stroke-opacity', '0.8');
        m.tick.setAttribute('stroke-width', '2');
        m.tick.removeAttribute('class');
        m.val.setAttribute('fill', '#ffffff');
        m.val.setAttribute('font-size', '28');
        if (m.pct) m.pct.setAttribute('fill', '#6FF26F');
        m.lbl.setAttribute('fill', '#a8c4b4');
        m.lbl.setAttribute('font-weight', '500');
      } else {
        m.tick.setAttribute('y2', '16');
        m.tick.setAttribute('stroke', '#6e937f');
        m.tick.setAttribute('stroke-opacity', '0.45');
        m.tick.setAttribute('stroke-width', '2');
        m.tick.removeAttribute('class');
        m.val.setAttribute('fill', '#7da48f');
        m.val.setAttribute('font-size', '28');
        if (m.pct) m.pct.setAttribute('fill', '#7da48f');
        m.lbl.setAttribute('fill', '#7da48f');
        m.lbl.setAttribute('font-weight', '500');
      }
    }
  }

  let manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    updateAt(tMs);
  };

  const start = performance.now();
  function loop(now) {
    if (manual) return;
    updateAt(now - start);
    requestAnimationFrame(loop);
  }
  updateAt(0);
  requestAnimationFrame(loop);
})();
